   if(polygons.Count>32768)throw new ArgumentException("Joined asphalt polygon cap");var sourceContours=exposedMask.Select(p=>p.Select(q=>new Point64((long)Math.Round(q.X*scale),(long)Math.Round(q.Z*scale))).ToArray()).ToArray();bool Exposed(Point64 a,Point64 b){var middle=new Point64((a.X+b.X)/2,(a.Y+b.Y)/2);foreach(var path in sourceContours)for(int i=0;i<path.Length;i++)if(Distance(middle,path[i],path[(i+1)%path.Length],out _)<=.00002*scale)return true;return false;}
