e,x,z);if(canonicalHeight!=null)y=canonicalHeight(polygon.OriginalTriangle,x,z,y);buffers.Weld.Add(key,index);buffers.XYZ.Add((float)(x-ox));buffers.XYZ.Add((float)(y-originY));buffers.XYZ.Add((float)(z-oz));return index;}
    if(restored.Count>3){var center=new Point64(RoundRational(restored.Aggregate(BigInteger.Zero,(sum,p)=>sum+p.X),restored.Count),RoundRational(restored.Aggregate(BigInteger.Zero,(sum,p)=>sum+p.Y),restored.Count));bool kernel=true;for(int i=0;i<restored.Count;i++)if(Cross(restored[i],restored[(i+1)%restored.Count],center).Sign>=0){kernel=false;break;}if(kernel){for(int i=0;i<restored.Count;i++)buffers.Indices.AddRange(new[]{V(center),V(restored[i]),V(restored[(i+1)%restored.Count])});continue;}}var pending=new List<Point64>(restored);while(pending.Count>3){int bestEar=-1;double bestQuality=-1;for(int i=0;i<pending.Count;i++){var a=pending[(i+pending.Count-1)%pending.Count];var b=pending[i];var c=pending[(i+1)%pending.Count];var cross=Cross(a,b,c);if(cross.Sign>=0)continue;bool contains=false;for(int j=0;j<pending.Count;j++){var p=pending[j];if((p.X==a.X&&p.Y==a.Y)||(p.X==b.X&&p.Y==b.Y)||(p.X==c.X&&p.Y==c.Y))continue;if(Cross(a,b,p).Sign<=0&&Cross(b,c,p).Sign<=0&&Cross(c,a,p).Sign<=0){contains=true;break;}}if(contains)continue;double l1=Math.Pow((double)(a.X-b.X),2)+Math.Pow((double)(a.Y-b.Y),2),l2=Math.Pow((double)(c.X-b.X),2)+Math.Pow((double)(c.Y-b.Y),2),l3=Math.Pow((double)(c.X-a.X),2)+Math.Pow((double)(c.Y-a.Y),2),quality=(double)BigInteger.Abs(cross)/Math.Max(l1,Math.Max(l2,l3));if(quality>bestQuality){bestQuality=quality;bestEar=i;}}if(bestEar<0)throw new ArgumentException("Asphalt ear cannot preserve all positive/collinear source controls");var ea=pending[(bestEar+pending.Count-1)%pending.Count];var eb=pending[bestEar];var ec=pending[(bestEar+1)%pending.Count];buffers.Indices.AddRange(new[]{V(ea),V(eb),V(ec)});pending.RemoveAt(bestEar);}if(Cross(pending[0],pending[1],pending[2]).Sign>=0)throw new ArgumentException("Asphalt final ear degenerate/backward");buffers.Indices.AddRange(pending.Select(V));}
